/* @autogenerated */
import { Injectable } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { ActivatedRouteSnapshot, CanActivateFn, Route, Router, UrlTree } from '@angular/router';
import { provideRouter } from '@angular/router';
import { firstValueFrom, Observable, of } from 'rxjs';
import { RouteAccessService } from './route-accessible.service';

function buildMockRouter(
  routes: Route[],
  rootSnapshot: Partial<ActivatedRouteSnapshot> = { routeConfig: null, children: [] },
): Router {
  return {
    config: routes,
    routerState: { snapshot: { root: rootSnapshot } },
    createUrlTree: (commands: any[]) => ({ commands }) as unknown as UrlTree,
  } as unknown as Router;
}

describe('RouteAccessService', () => {
  let service: RouteAccessService;

  function setup(routes: Route[] = []) {
    TestBed.configureTestingModule({
      providers: [provideRouter(routes), RouteAccessService],
    });
    service = TestBed.inject(RouteAccessService);
  }

  function setupWithMockRouter(routes: Route[], rootSnapshot?: Partial<ActivatedRouteSnapshot>) {
    const mockRouter = buildMockRouter(routes, rootSnapshot);
    TestBed.configureTestingModule({
      providers: [{ provide: Router, useValue: mockRouter }, RouteAccessService],
    });
    service = TestBed.inject(RouteAccessService);
  }

  describe('checkRouteGuards', () => {
    it('returns false when no route matches the url', () => {
      setup([{ path: 'home', component: class {} }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('unknown').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });

    it('returns true when route has no canActivate guards', () => {
      setup([{ path: 'home', component: class {} }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('home').subscribe((v) => (result = v));
      expect(result).toBe(true);
    });

    it('returns false when a guard returns false synchronously', () => {
      const guard: CanActivateFn = () => false;
      setup([{ path: 'protected', component: class {}, canActivate: [guard] }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('protected').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });

    it('returns false when a guard returns a UrlTree', () => {
      let capturedRouter!: Router;
      const guard: CanActivateFn = (_route, _state) => {
        capturedRouter = TestBed.inject(Router);
        return capturedRouter.createUrlTree(['/login']);
      };
      setup([{ path: 'protected', component: class {}, canActivate: [guard] }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('protected').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });

    it('returns the observable emitted by a guard that returns Observable<boolean> true', () => {
      const guard: CanActivateFn = (): Observable<boolean> => of(true);
      setup([{ path: 'protected', component: class {}, canActivate: [guard] }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('protected').subscribe((v) => (result = v));
      expect(result).toBe(true);
    });

    it('returns the observable when guard emits false via Observable', () => {
      const guard: CanActivateFn = (): Observable<boolean> => of(false);
      setup([{ path: 'protected', component: class {}, canActivate: [guard] }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('protected').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });

    it('returns true when guard returns true synchronously', () => {
      const guard: CanActivateFn = () => true;
      setup([{ path: 'protected', component: class {}, canActivate: [guard] }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('protected').subscribe((v) => (result = v));
      expect(result).toBe(true);
    });

    it('returns true when multiple guards all pass', () => {
      const guardA: CanActivateFn = () => true;
      const guardB: CanActivateFn = () => true;
      setup([{ path: 'multi', component: class {}, canActivate: [guardA, guardB] }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('multi').subscribe((v) => (result = v));
      expect(result).toBe(true);
    });

    it('stops at the first failing guard and returns false', () => {
      const guardFail: CanActivateFn = () => false;
      const guardPass: CanActivateFn = () => true;
      setup([{ path: 'multi', component: class {}, canActivate: [guardFail, guardPass] }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('multi').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });

    it('evaluates every async guard, not only the first one', () => {
      const guardA: CanActivateFn = () => of(true);
      const guardB: CanActivateFn = () => of(false);
      setup([{ path: 'multi', component: class {}, canActivate: [guardA, guardB] }]);
      let result: boolean | undefined;
      service.checkRouteGuards('multi').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });

    it('does not run later guards once one rejects', () => {
      const later = jasmine.createSpy('later').and.returnValue(true);
      setup([{ path: 'multi', component: class {}, canActivate: [() => of(false), later] }]);
      service.checkRouteGuards('multi').subscribe();
      expect(later).not.toHaveBeenCalled();
    });

    it('awaits guards that return a Promise', async () => {
      setup([{ path: 'protected', component: class {}, canActivate: [() => Promise.resolve(false)] }]);
      await expectAsync(firstValueFrom(service.checkRouteGuards('protected'))).toBeResolvedTo(false);
    });

    it('treats an async UrlTree as not accessible', () => {
      const guard: CanActivateFn = () => of(TestBed.inject(Router).createUrlTree(['/login']));
      setup([{ path: 'protected', component: class {}, canActivate: [guard] }]);
      let result: boolean | undefined;
      service.checkRouteGuards('protected').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });

    it('passes the route data and url params (inherited from parents) to the guard', () => {
      let seen: ActivatedRouteSnapshot | undefined;
      let seenUrl: string | undefined;
      const guard: CanActivateFn = (route, state) => {
        seen = route;
        seenUrl = state.url;
        return true;
      };
      setup([
        {
          path: ':language/:tenant',
          component: class {},
          children: [
            { path: 'users/:id', component: class {}, data: { permission: 'users.read' }, canActivate: [guard] },
          ],
        },
      ]);
      service.checkRouteGuards('es/acme/users/42').subscribe();

      expect(seen!.data).toEqual({ permission: 'users.read' });
      expect(seen!.params).toEqual({ language: 'es', tenant: 'acme', id: '42' });
      expect(seen!.paramMap.get('id')).toBe('42');
      expect(seen!.url.map((s) => s.path)).toEqual(['users', '42']);
      expect(seenUrl).toBe('/es/acme/users/42');
    });

    it('runs canActivate of the parents and canActivateChild of the ancestors', () => {
      const calls: string[] = [];
      setup([
        {
          path: 'admin',
          component: class {},
          canActivate: [() => (calls.push('parent'), true)],
          canActivateChild: [(child) => (calls.push('child:' + child.url[0].path), false)],
          children: [{ path: 'settings', component: class {}, canActivate: [() => (calls.push('leaf'), true)] }],
        },
      ]);
      let result: boolean | undefined;
      service.checkRouteGuards('admin/settings').subscribe((v) => (result = v));

      expect(result).toBe(false);
      expect(calls).toEqual(['parent', 'child:settings']);
    });

    it('supports class-based guards', () => {
      @Injectable({ providedIn: 'root' })
      class DenyGuard {
        canActivate() {
          return of(false);
        }
      }
      setup([{ path: 'protected', component: class {}, canActivate: [DenyGuard] }]);
      let result: boolean | undefined;
      service.checkRouteGuards('protected').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });

    it('returns false when a guard throws', () => {
      const guard: CanActivateFn = () => {
        throw new Error('boom');
      };
      setup([{ path: 'protected', component: class {}, canActivate: [guard] }]);
      let result: boolean | undefined;
      service.checkRouteGuards('protected').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });
  });

  describe('isUrlActive', () => {
    it('returns false when no route matches', () => {
      setup([{ path: 'home', component: class {} }]);
      expect(service.isUrlActive('unknown')).toBe(false);
    });

    it('returns false when route matches but is not the active route', () => {
      setup([{ path: 'home', component: class {} }]);
      expect(service.isUrlActive('home')).toBe(false);
    });

    it('returns true when the route config matches the active route snapshot', () => {
      const routes: Route[] = [{ path: 'home', component: class {} }];
      const fakeSnapshot = { routeConfig: routes[0], children: [] };
      setupWithMockRouter(routes, fakeSnapshot as unknown as ActivatedRouteSnapshot);
      expect(service.isUrlActive('home')).toBe(true);
    });

    it('returns true when the route config matches a child snapshot', () => {
      const routes: Route[] = [{ path: 'home', component: class {} }];
      const childSnapshot = { routeConfig: routes[0], children: [] };
      const rootSnapshot = { routeConfig: null, children: [childSnapshot] };
      setupWithMockRouter(routes, rootSnapshot as unknown as ActivatedRouteSnapshot);
      expect(service.isUrlActive('home')).toBe(true);
    });

    it('returns false when nested snapshots do not match the route', () => {
      const routes: Route[] = [
        { path: 'home', component: class {} },
        { path: 'other', component: class {} },
      ];
      const childSnapshot = { routeConfig: routes[1], children: [] };
      const rootSnapshot = { routeConfig: null, children: [childSnapshot] };
      setupWithMockRouter(routes, rootSnapshot as unknown as ActivatedRouteSnapshot);
      expect(service.isUrlActive('home')).toBe(false);
    });
  });

  describe('findMostSpecificRoute (via checkRouteGuards)', () => {
    it('returns false when route path is undefined', () => {
      setupWithMockRouter([{ component: class {} } as Route]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('home').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });

    it('matches a route with a dynamic segment (:id)', () => {
      setup([{ path: 'users/:id', component: class {} }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('users/42').subscribe((v) => (result = v));
      expect(result).toBe(true);
    });

    it('does not match when url has fewer segments than route path', () => {
      setup([{ path: 'users/:id/profile', component: class {} }]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('users').subscribe((v) => (result = v));
      expect(result).toBe(false);
    });

    it('returns child route for nested paths', () => {
      const childGuard: CanActivateFn = () => true;
      setup([
        {
          path: 'admin',
          component: class {},
          children: [{ path: 'settings', component: class {}, canActivate: [childGuard] }],
        },
      ]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('admin/settings').subscribe((v) => (result = v));
      expect(result).toBe(true);
    });

    it('falls back to parent route when no child matches', () => {
      setup([
        {
          path: 'admin',
          component: class {},
          children: [{ path: 'settings', component: class {} }],
        },
      ]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('admin').subscribe((v) => (result = v));
      expect(result).toBe(true);
    });

    it('skips routes with empty path', () => {
      setup([
        { path: '', component: class {} },
        { path: 'home', component: class {} },
      ]);
      let result: boolean | UrlTree | undefined;
      service.checkRouteGuards('home').subscribe((v) => (result = v));
      expect(result).toBe(true);
    });
  });
});
